(tenant_id = #{filter.tenantId} OR tenant_id = 'default')
AND created_by = #{filter.ownerId}

    AND (LOCATE(LOWER(#{filter.query}), LOWER(COALESCE(name, ''))) > 0 OR LOCATE(LOWER(#{filter.query}), LOWER(COALESCE(description, ''))) > 0 OR LOCATE(LOWER(#{filter.query}), LOWER(COALESCE(source_filename, ''))) > 0 OR LOCATE(LOWER(#{filter.query}), LOWER(COALESCE(source_type, ''))) > 0)

mapper.select:
SELECT knowledge_id, name, description, source_type, source_filename, chunk_count, content_length, tenant_id, created_by, created_at, updated_at FROM knowledge_entry WHERE 
ORDER BY created_at DESC, knowledge_id DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT COUNT(*) AS count, COALESCE(SUM(chunk_count), 0) AS chunks,
    COALESCE(SUM(content_length), 0) AS characters
FROM knowledge_entry WHERE tenant_id = #{tenantId} AND created_by = #{userId}
